import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"39、【蹇】 艮下坎上","description":"子夏易傳 - 39、【蹇】 艮下坎上","frontmatter":{"title":"39、【蹇】 艮下坎上","description":"子夏易傳 - 39、【蹇】 艮下坎上"},"headers":[],"relativePath":"classics/zixia/041.md","filePath":"classics/zixia/041.md"}'),i={name:"classics/zixia/041.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_39、【蹇】-艮下坎上" tabindex="-1">39、【蹇】 艮下坎上 <a class="header-anchor" href="#_39、【蹇】-艮下坎上" aria-label="Permalink to “39、【蹇】 艮下坎上”">​</a></h1><p>卦辭：蹇，利西南，不利東北，利見大人，貞吉。</p><p>彖曰：蹇，難也。險在前也。見險而能止知矣哉。蹇，利西南，往得中也。不利東北，其道窮也。利見大人，往有功也。當位貞吉，以正邦也。蹇之時用大矣哉。</p><p>子夏：見險而止，難其進也。度徳而處，將以營之也。蹇利西南，眾順待治，往而得中，因眾而險下濟也。不利東北，遂止而不以進，道窮而不能濟於蹇也。</p><p>象曰：山上有水，蹇。君子以反身修徳。</p><p>子夏：山上有水，難之所也，有徳者乃能濟之。君子反身修徳，將以為也。</p><p>初六，往蹇來譽。</p><p>象曰：往蹇來譽，冝待也。</p><p>子夏：柔止於初，見險而待，保下之安也，故往則之蹇，來則見譽矣。</p><p>六二，王臣蹇蹇，匪躬之故。</p><p>象曰：王臣蹇蹇，終無尤也。</p><p>子夏：得位居正而應於尊，竭力致身以輔於上，救其蹇於蹇中也。五能蹇而已竭焉，可以保其終也。</p><p>九三，往蹇來反。</p><p>象曰：往蹇來反，內喜之也。</p><p>子夏：得位於上，內有其人，安之所也。故往則涉險難中，來則內喜，得其反而安矣。</p><p>六四，往蹇來連。</p><p>象曰：往蹇來連，當位實也。</p><p>子夏：蹇非得中，不能濟下也。四得位矣，可以承其上，而不可獨濟也。故往則蹇矣，來則當其位而連於實，得其所附也。</p><p>九五，大蹇朋來。</p><p>象曰：大蹇朋來，以中節也。</p><p>子夏：在蹇之中正，而得大位，濟蹇之大者也。居於中正，而能裁製節度，使賢不肖，各當其所，故用朋來，而求伸也。</p><p>上六，往蹇來碩吉。利見大人。</p><p>象曰：往蹇來碩，志在內也。利見大人，以從貴也。</p><p>子夏：柔居陰極內有其應，五極其蹇已，又附之，故往則道窮。求得內附，故大且吉。利見以從，貴也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
